create table if not exists jlc.rgl_asset_links (link_code text primary key,corridor_code text not null references jlc.corridors(corridor_code) on delete cascade,jlc_node_code text references jlc.nodes(node_code) on delete cascade,rgl_entity_type text not null check (rgl_entity_type in ('CORRIDOR','INFRASTRUCTURE_NODE','RAIL_NETWORK','RAIL_TERMINAL','LOGISTICS_HUB','INTERMODAL_CONNECTION','DRONE_HUB','DRONE_DELIVERY_ZONE','SPATIAL_REGISTRY_LINK')),rgl_entity_id uuid not null,relationship_role text not null,verification_state text not null default 'PENDING_VERIFICATION' check (verification_state in ('PROPOSED','PENDING_VERIFICATION','VERIFIED_REFERENCE','ACTIVE','SUSPENDED','REJECTED','ARCHIVED')),evidence_reference text,created_at timestamptz not null default now(),unique(corridor_code,rgl_entity_type,rgl_entity_id,relationship_role)); create table if not exists jlc.wim_links (link_code text primary key,corridor_code text not null references jlc.corridors(corridor_code) on delete cascade,wim_trade_corridor_id uuid not null,relationship_role text not null,verification_state text not null default 'PENDING_VERIFICATION' check (verification_state in ('PROPOSED','PENDING_VERIFICATION','VERIFIED_REFERENCE','ACTIVE','SUSPENDED','REJECTED','ARCHIVED')),evidence_reference text,created_at timestamptz not null default now(),unique(corridor_code,wim_trade_corridor_id,relationship_role)); alter table jlc.rgl_asset_links enable row level security; alter table jlc.wim_links enable row level security; grant select,insert,update,delete on jlc.rgl_asset_links,jlc.wim_links to service_role; revoke all on jlc.rgl_asset_links,jlc.wim_links from anon,authenticated; create policy service_role_all on jlc.rgl_asset_links for all to service_role using (true) with check (true); create policy service_role_all on jlc.wim_links for all to service_role using (true) with check (true); insert into jlc.rgl_asset_links(link_code,corridor_code,rgl_entity_type,rgl_entity_id,relationship_role,verification_state,evidence_reference) select 'JLC-RGL-CORRIDOR-001','JLC-001','CORRIDOR',id,'REGIONAL_CORRIDOR_PARENT','VERIFIED_REFERENCE','RGL:RGL-CAR-JAM' from rgl.corridors where code='RGL-CAR-JAM' on conflict do nothing; insert into jlc.rgl_asset_links(link_code,corridor_code,jlc_node_code,rgl_entity_type,rgl_entity_id,relationship_role,verification_state,evidence_reference) select 'JLC-RGL-NODE-KINGSTON-001','JLC-001','JLC-NODE-KINGSTON-WESTLANDS','INFRASTRUCTURE_NODE',id,'MARITIME_GATEWAY_REFERENCE','PENDING_VERIFICATION','RGL:PORT-OF-KINGSTON' from rgl.infrastructure_nodes where name='Port of Kingston / Kingston Container Terminal' on conflict do nothing; insert into jlc.wim_links(link_code,corridor_code,wim_trade_corridor_id,relationship_role,verification_state,evidence_reference) select 'JLC-WIM-001','JLC-001',id,'TRADE_CORRIDOR_INTERFACE','VERIFIED_REFERENCE','WIM:UNITED-STATES-JAMAICA-MULTIMODAL' from wim.trade_corridors where name='United States–Jamaica Multimodal Corridor' on conflict do nothing;
